-- Seed one eval arm's database. Run once per arm per repeat, after the engine
-- has booted the migrations in and stopped again.
--
--   psql -v ON_ERROR_STOP=1 \
--        -v model=… -v model_label=… -v model_provider=… -v reasoning_effort=… \
--        -f seed.sql
--
-- Everything here is literal. No id is generated, no timestamp is `now()`, and
-- no vector is computed, because the two arms have to hash identically and a
-- re-seed has to reproduce the first one exactly.
--
-- Two things the specification lists here live elsewhere, because the engine
-- does not read them from `preferences`:
--
--   * The user profile is an artifact, `data/artifacts/user_profile.md`, so it
--     is part of the fixture tree and lands in the filesystem digest.
--   * The embedding model is resolved from `LUCIDOS_EMBEDDING_MODEL`, so the
--     run script pins it in the environment. `memory_entries.embedding_model`
--     below records which model actually produced these vectors.

BEGIN;

-- Preferences. An arm's own rows are NOT written here: the harness writes them
-- per arm, and they are the rows the digest excludes. There are three, named by
-- `lucidos_eval::arm::ARM_PREFERENCE_KEYS`: the mode's flag and the two numbers
-- of its schedule.
DELETE FROM preferences;
  -- Without this the engine persists `content: None` on every section, so a
  -- capture carries names and char counts and no bodies. Every run before
  -- ADR 0110 recorded nothing replayable. It is seeded here rather than per
  -- arm, so both arms carry it and the digest still matches.
  ('capture_context',       'true',              NULL, '2026-01-01 00:00:00+00');

-- The model registry holds the pinned entry and nothing else, so the picker
-- cannot resolve to a different model between arms or between repeats.
DELETE FROM models;
-- `context_window` is the budget-pressure knob (ADR 0110 decision 9). It is
-- substituted UNQUOTED so an unset run gets a real NULL, and the engine then
-- infers the window from the model id exactly as it does in production.
                    created_at, updated_at)
VALUES (:'model', :'model_label', :'model_provider', 0, 'builtin', TRUE, :context_window,
        '2026-01-01 00:00:00+00', '2026-01-01 00:00:00+00');

DELETE FROM memory_entries;

-- BEGIN GENERATED memory_entries
-- Written by `cargo run -p lucidos-eval --features fixture-gen -- generate-memory-fixture`
-- from fixtures/memory-seed.toml. Never edit by hand: the vectors are model
-- output and the digest depends on them byte for byte.
-- END GENERATED memory_entries

COMMIT;
